CustomField.formula:
NOT(
            AND(
                OR(
                    ISPICKVAL(Pickup_status__c, "完了"),
                    ISPICKVAL(Pickup_status__c, "案件キャンセル")
                ),
                OR(
                    ISPICKVAL(Document_status__c, "完了"),
                    ISPICKVAL(Document_status__c, "案件キャンセル")
                ),
                OR(
                    ISPICKVAL(Transfer_status__c, "振込完了"),
                    ISPICKVAL(Transfer_status__c, "案件キャンセル")
                )
            )
        )
